# Human-readable size formatter
def format_bytes(n):
    """Convert bytes to a human-readable string.
    Returns sizes like '1.5 KB' or '2.3 GB'.
    """
    if n < 1024:
        return f"{n/1024:.1f} B"
    elif n < 1048576:
        return f"{n/1024:.1f} KB"
    elif n < 1073741824:
        return f"{n/1048576:.1f} MB"
    else:
        return f"{n/1073741824:.1f} GB"

